def _parse_root(name: str, input: str | JsonValue) -> ParseResult[JsonValue]:
    try:
        raw = _to_safe_json(
            json.loads(
                input,
                parse_float=Decimal,
                parse_constant=_reject_json_constant,
            )
            if isinstance(input, str)
            else input
        )
    except (TypeError, ValueError, InvalidOperation, RecursionError) as error:
        return {
            "ok": False,
            "diagnostics": ({
                "path": "",
                "code": "invalid_json",
                "severity": "error",
                "message": str(error) or "Invalid JSON",
            },),
        }
    diagnostics: list[ParseDiagnostic] = []
    _check_node(_SCHEMAS[name], raw, "", diagnostics)
    frozen = tuple(diagnostics)
    if any(item["severity"] == "error" for item in diagnostics):
        return {"ok": False, "raw": raw, "diagnostics": frozen}
    return {"ok": True, "value": raw, "raw": raw, "diagnostics": frozen}


def _check_node(schema: _SchemaNode, value: JsonValue, path: str, diagnostics: list[ParseDiagnostic]) -> None:
    kind = schema["kind"]
    if kind == "any":
        return
    if kind == "never":
        _error(diagnostics, path, "invalid_type", "Value is forbidden")
    elif kind == "null":
        if value is not None:
            _error(diagnostics, path, "invalid_type", "Expected null")
    elif kind == "boolean":
        if type(value) is not bool:
            _error(diagnostics, path, "invalid_type", "Expected boolean")
    elif kind == "integer":
        if not _is_integer(value) or abs(value) > 9_007_199_254_740_991:
            _error(diagnostics, path, "invalid_type", "Expected safely representable integer")
    elif kind == "number":
        if not _is_number(value):
            _error(diagnostics, path, "invalid_type", "Expected finite number")
    elif kind == "string":
        if not isinstance(value, str):
            _error(diagnostics, path, "invalid_type", "Expected string")
    elif kind == "literal":
        if not _same_json(value, schema["value"]):
            _error(diagnostics, path, "literal_mismatch", f"Expected {_display_json(schema['value'])}")
    elif kind == "enum":
        if any(_same_json(candidate, value) for candidate in schema["values"]):
            return
        if schema["open_strings"] and isinstance(value, str):
            diagnostics.append({
                "path": path,
                "code": "unknown_enum",
                "severity": "warning",
                "message": f"Unknown enum value {_display_json(value)} was preserved",
            })
        else:
            _error(diagnostics, path, "invalid_type", "Value does not match the enum's scalar type")
    elif kind == "array":
        if not isinstance(value, list):
            _error(diagnostics, path, "invalid_type", "Expected array")
            return
        for index, item in enumerate(value):
            _check_node(schema["items"], item, f"{path}/{index}", diagnostics)
    elif kind == "object":
        if not isinstance(value, dict):
            _error(diagnostics, path, "invalid_type", "Expected object")
            return
        for forbidden_set in schema["forbidden_property_sets"]:
            if all(key in value for key in forbidden_set):
                _error(
                    diagnostics,
                    path,
                    "invalid_type",
                    f"Forbidden property combination: {', '.join(forbidden_set)}",
                )
        for property in schema["properties"]:
            wire_name = property["wire_name"]
            if wire_name not in value:
                if property["required"]:
                    _error(
                        diagnostics,
                        _join_path(path, wire_name),
                        "missing_required",
                        "Required property is absent",
                    )
            else:
                _check_node(property["shape"], value[wire_name], _join_path(path, wire_name), diagnostics)
    elif kind == "intersection":
        for variant in schema["variants"]:
            _check_node(variant, value, path, diagnostics)
    elif kind == "ref":
        _check_node(_SCHEMAS[schema["name"]], value, path, diagnostics)
    elif kind == "union":
        _check_union(schema, value, path, diagnostics)


def _check_union(schema: _SchemaNode, value: JsonValue, path: str, diagnostics: list[ParseDiagnostic]) -> None:
    discriminator = schema.get("discriminator")
    if discriminator is not None:
        if not isinstance(value, dict) or not isinstance(value.get(discriminator), str):
            _error(diagnostics, _join_path(path, discriminator), "invalid_type", "Expected string discriminator")
            return
        actual = value[discriminator]
        branch = next(
            (
                variant
                for variant in schema["variants"]
                if _discriminator_value(variant, discriminator) == actual
            ),
            None,
        )
        if branch is None:
            diagnostics.append({
                "path": path,
                "code": "unknown_variant",
                "severity": "warning",
                "message": f"Unknown {discriminator} variant {_display_json(actual)} was preserved",
            })
            return
        branch_diagnostics: list[ParseDiagnostic] = []
        _check_node(branch, value, path, branch_diagnostics)
        diagnostics.extend(branch_diagnostics)
        if any(item["severity"] == "error" for item in branch_diagnostics):
            diagnostics.append({
                "path": path,
                "code": "invalid_known_variant",
                "severity": "error",
                "message": f"Known {discriminator} variant is malformed",
            })
        return

    attempts: list[list[ParseDiagnostic]] = []
    for variant in schema["variants"]:
        attempt: list[ParseDiagnostic] = []
        _check_node(variant, value, path, attempt)
        attempts.append(attempt)
    matches = [
        attempt
        for attempt in attempts
        if not any(item["severity"] == "error" for item in attempt)
    ]
    if not matches:
        _error(diagnostics, path, "no_union_match", "Value matches no union branch")
    elif schema["mode"] == "oneOf" and len(matches) > 1:
        _error(diagnostics, path, "ambiguous_union", "Value matches more than one union branch")
    else:
        diagnostics.extend(matches[0])


def _discriminator_value(schema: _SchemaNode, property: str) -> str | None:
    kind = schema["kind"]
    if kind == "ref":
        return _discriminator_value(_SCHEMAS[schema["name"]], property)
    if kind == "intersection":
        for variant in schema["variants"]:
            value = _discriminator_value(variant, property)
            if value is not None:
                return value
    if kind == "object":
        for field in schema["properties"]:
            if field["wire_name"] == property:
                shape = field["shape"]
                if shape["kind"] == "literal" and isinstance(shape["value"], str):
                    return shape["value"]
    return None


def _to_safe_json(value: object) -> JsonValue:
    if value is None or type(value) in (str, bool, int):
        return cast(JsonPrimitive, value)
    if type(value) is float:
        if not math.isfinite(value):
            raise ValueError("Input contains a non-finite number")
        return value
    if type(value) is Decimal:
        if not value.is_finite():
            raise ValueError("Input contains a non-finite number")
        return value
    if isinstance(value, list):
        return [_to_safe_json(item) for item in value]
    if isinstance(value, dict):
        result: JsonObject = {}
        for key, child in value.items():
            if not isinstance(key, str):
                raise TypeError("JSON object keys must be strings")
            result[key] = _to_safe_json(child)
        return result
    raise TypeError("Input is not a JSON value")


def _encode_json(value: JsonValue) -> str:
    return _encode_json_value(_to_safe_json(value))


def _encode_json_value(value: JsonValue) -> str:
    if value is None:
        return "null"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, str):
        return _escape_surrogates(
            json.dumps(value, ensure_ascii=False, separators=(",", ":"))
        )
    if type(value) is int:
        return str(value)
    if type(value) is Decimal:
        if not value.is_finite():
            raise ValueError("Input contains a non-finite number")
        return str(value)
    if type(value) is float:
        return json.dumps(value, allow_nan=False, separators=(",", ":"))
    if isinstance(value, list):
        return "[" + ",".join(_encode_json_value(item) for item in value) + "]"
    return "{" + ",".join(
        _encode_json_value(key) + ":" + _encode_json_value(child)
        for key, child in cast(JsonObject, value).items()
    ) + "}"


def _is_number(value: JsonValue) -> bool:
    return (
        type(value) is int
        or (type(value) is float and math.isfinite(value))
        or (type(value) is Decimal and value.is_finite())
    )


def _is_integer(value: JsonValue) -> bool:
    if type(value) is int:
        return True
    if type(value) is float:
        return math.isfinite(value) and value.is_integer()
    return type(value) is Decimal and value.is_finite() and value == value.to_integral_value()


def _same_json(left: JsonValue, right: JsonValue) -> bool:
    if _is_number(left) and _is_number(right):
        return left == right
    if type(left) is not type(right):
        return False
    if isinstance(left, list):
        right_list = cast(list[JsonValue], right)
        return len(left) == len(right_list) and all(
            _same_json(left_item, right_item)
            for left_item, right_item in zip(left, right_list)
        )
    if isinstance(left, dict):
        right_object = cast(JsonObject, right)
        return left.keys() == right_object.keys() and all(
            _same_json(left[key], right_object[key]) for key in left
        )
    return left == right


def _display_json(value: JsonValue) -> str:
    return _encode_json(value)


def _escape_surrogates(value: str) -> str:
    return "".join(
        f"\\u{ord(character):04x}" if 0xD800 <= ord(character) <= 0xDFFF else character
        for character in value
    )


def _join_path(path: str, key: str) -> str:
    return f"{path}/{key.replace('~', '~0').replace('/', '~1')}"


def _error(
    diagnostics: list[ParseDiagnostic],
    path: str,
    code: DiagnosticCode,
    message: str,
) -> None:
    diagnostics.append({"path": path, "code": code, "severity": "error", "message": message})


def _reject_json_constant(value: str) -> Never:
    raise ValueError(f"Invalid JSON constant {value}")


